text:
{
  "questions": [
    {
      "n": 1,
      "start": "Wie viel haben die Studien und die Ausstellung",
      "end": "zur Zentrumsplanung Gerbe- und Poststrasse gekostet?"
    },
    {
      "n": 2,
      "start": "Wo sieht der Stadtrat den konkreten Nutzen",
      "end": "dieses Projekts?"
    },
    {
      "n": 3,
      "start": "Wie kann die Stadt konkret Einfluss nehmen auf die Gestaltung",
      "end": "der Bauten an der Gerbe- und Poststrasse?"
    },
    {
      "n": 4,
      "start": "Mit der Entlassung des Gebäudes Gerbestrasse 3 aus dem Inventar",
      "end": "der schützenswerten Bauten wird der Weg frei für dessen Abriss und Neubau durch die Firma Uster AG."
    },
    {
      "n": 5,
      "start": "Wie weit sind die Pläne für Hochhäuser an diesen Strassen",
      "end": "wie sieht der Fahrplan für solche Bauten ungefähr aus?"
    },
    {
      "n": 6,
      "start": "Wird sich der Stadtrat auch für eine Umgestaltung der unteren Zugerstrasse mit",
      "end": "Verkehrsberuhigung engagieren (auch wenn diese Kantonsstrasse grundsätzlich der Planungshoheit des Kantons unterliegt)? Wenn ja: wann?"
    },
    {
      "n": 7,
      "start": "Wird an der unteren Zugerstrasse eine Temporeduktion verfügt?",
      "end": ""
    },
    {
      "n": 8,
      "start": "Plant die Stadt weitere Projekte zur Zentrumsplanung mit Studien und",
      "end": "Ausstellungen?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Studien und Ausstellung zur Zentrumsplanung Gerbeund Poststrasse",
      "end": "haben insgesamt Fr. 407‘421.- gekostet; an diese Kosten hat der Kanton einen Beitrag von Fr. 120‘000.- geleistet."
    },
    {
      "n": 2,
      "start": "Die Stärke der Zentrumsplanung ist die grossflächige und interdisziplinäre",
      "end": "Erkundung städtebaulicher und verkehrstechnischer Lösungen."
    },
    {
      "n": 3,
      "start": "Der Stadtrat sieht seine Aufgabe darin, die Ergebnisse der Zentrumsplanung",
      "end": "durch eine aktive Begleitung der Bauherrschaft (z.B. Coop) oder mit einem öffentlichen Gestaltungsplan (Gerbeplatz) zu sichern."
    },
    {
      "n": 4,
      "start": "Im Rahmen der Zentrumsplanung wurde festgelegt, dass eine Renovation bzw.",
      "end": "ein Ersatzbau an der Gerbestrasse 1 und 3 in ähnlichem Umfang wie das bestehende Bauvolumen realisiert werden könne."
    },
    {
      "n": 5,
      "start": "Eigentliche Hochhäuser im Sinne von § 282 PBG (höher als 25 Meter) stehen",
      "end": "nicht zur Diskussion. Die zurzeit laufenden Planungen gehen davon aus, dass im Rahmen von Gestaltungsplänen lediglich - wenn überhaupt - hohe Häuser (max. 25 Meter) vorgesehen werden."
    },
    {
      "n": 6,
      "start": "Der Stadtrat hat sich intensiv mit hohen Vertretern des Kantons zum Thema",
      "end": "Temporeduktion auseinandergesetzt. Die Planungshoheit bei der Umgestaltung der unteren Zugerstrasse liegt beim Kanton. Die Stadt kann nur beschränkt mitreden."
    },
    {
      "n": 7,
      "start": "Nein, siehe Antwort 6.",
      "end": ""
    },
    {
      "n": 8,
      "start": "Aus heutiger Sicht ist keine weitere Ausstellung geplant, hingegen ist in naher",
      "end": "Zukunft die Vorlage eines Gestaltungsplans für das Gebiet Gerbeplatz vorgesehen, welcher öffentlich aufgelegt wird."
    }
  ],
  "submitter": "Hansjörg Schmid, SP Wädenswil",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": null
}
